"""EventBus: handlers subscribe to topics and receive the events published there."""

from __future__ import annotations

import fnmatch
import logging
from collections.abc import Callable
from typing import Any

Handler = Callable[[Any], object]
log = logging.getLogger("eventbus")


class EventBus:
    """Calls the handlers of a topic one after another, in the publishing thread."""

    def __init__(self) -> None:
        self._topics: dict[str, list[tuple[int, Handler]]] = {}
        self._next_token = 1

    def subscribe(self, topic: str, handler: Handler) -> int:
        """Register handler for topic and return a token for unsubscribe()."""
        token = self._next_token
        self._next_token += 1
        self._topics.setdefault(topic, []).append((token, handler))
        return token

    def unsubscribe(self, token: int) -> None:
        """Remove the subscription that subscribe() returned this token for."""
        for subs in self._topics.values():
            for index, (sub_token, _) in enumerate(subs):
                if sub_token == token:
                    del subs[index]
                    return

    def publish(self, topic: str, event: Any) -> int:
        """Send event to every handler of topic and return how many handlers ran."""
        handlers = [handler for _, handler in self._topics.get(topic, [])]
        for handler in handlers:
            try:
                handler(event)
            except Exception:
                log.exception("handler failed")
        return len(handlers)

