"""Recorder: a handler that keeps every event it receives, handy in tests."""

from __future__ import annotations

from typing import Any


class Recorder:
    """Call it with an event to record it; events holds them in arrival order."""

    def __init__(self) -> None:
        self.events: list[Any] = []

    def __call__(self, event: Any) -> None:
        self.events.append(event)

    def clear(self) -> None:
        """Forget every recorded event."""
        self.events.clear()

    def last(self) -> Any:
        """The most recent event, or None when nothing has arrived yet."""
        return self.events[-1] if self.events else None

